def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    seen = [[False] * w for _ in range(h)]
    objects = []

    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            if color != background and len(cells) >= 4:
                objects.append({
                    "color": color,
                    "cells": set(cells),
                    "rmin": min(y for y, x in cells),
                    "rmax": max(y for y, x in cells),
                    "cmin": min(x for y, x in cells),
                    "cmax": max(x for y, x in cells),
                })

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background:
                continue
            if any((r, c) in obj["cells"] for obj in objects):
                continue

            candidates = [
                obj for obj in objects
                if obj["rmin"] <= r <= obj["rmax"]
                and obj["cmin"] <= c <= obj["cmax"]
            ]
            if not candidates:
                out[r][c] = background
                continue

            def score(obj):
                return sum(
                    (r + dy, c + dx) in obj["cells"]
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))
                )

            best = max(candidates, key=score)
            out[r][c] = best["color"]

    return out
